using System.Collections.Generic;
namespace KAONOMI.Core.Models
{
    /// <summary>
    /// LLM completion record: prompt, response, model, and metadata.
    /// </summary>
    public class Completion : EntityBase, ISoftDeletable, ITagged
    {
        /// <summary>Never erased: marked deleted instead (<see cref="ISoftDeletable"/>).</summary>
        public bool isDeleted { get; set; } = false;


        /// <summary>text sent to the model.</summary>
        public string prompt { get; set; } = string.Empty;
        /// <summary>Response generated by the model.</summary>
        public string completion { get; set; } = string.Empty;
        public string rawCompletion { get; set; } = string.Empty;
        public string topic { get; set; }
        /// <summary>Identifier of the model used.</summary>
        public string model { get; set; } = string.Empty;
        /// <summary>Language or locale of the completion.</summary>
        public string language { get; set; }
        /// <summary>Logical collection or index grouping (default generic).</summary>
        public string? collectionName { get; set; } = "generic";
        /// <summary>Additional metadata (typed key/value pairs).</summary>
        public List<MetaData> metadatas { get; set; } = new List<MetaData>();
        public List<WordCountByTerm> wordCounts { get; set; } = new List<WordCountByTerm>();
        
    }

    public class WordCountByTerm
    {
        public string term { get; set; }
        public int count { get; set; }
        public string storedIn { get; set; }
    }
}
